# Own-wording items of Grim Hollow Campaign Guide (2024). Row shape as tee24_item.py: [name, type, rarity, attune, text, opts].
# This book has no baseitem. Weapons and armor are plain items that carry base or WPN.
# Item groups (Damglesvir, Hearthfire Breastplate, Indorius's Crown, Ulmyr's Eye) are covered by their Aspirant, Adept and Master members.
# Magic variants (Lycan Weapon, Paralyzing Bolt, Shadowsteel Blades, Tormach's Blessed Weapon) are generic rows at the end.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
MASTERY = {}
WDESC = {}

def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

# ---- Wondrous items, common to uncommon
add("Banshee Box", "Wondrous Item", "Common", 0, "An ivory music box inlaid with silver scenes of violence. After holding it for 1 minute, you can use a Magic action to command it to play a sound or phrase of your choice for up to 1 minute. Once the lid is open, the sound loops until it is closed, and the lid shuts if you travel more than 300 ft away. You choose whether it carries in a 5-ft, 30-ft or 120-ft radius Emanation.")
add("Blood Capsule", "Wondrous Item", "Common", 0, "A cylindrical flask etched with arcane runes. Humanoid blood stored in it stays fresh for up to 1 year. It holds enough blood to feed a vampire for 1 day.")
add("Bliss", "Wondrous Item", "Uncommon", 0, "A small white pellet of magical powder. A Humanoid who swallows it feels calm and happy for 1d4 hours, gaining Immunity to the Frightened condition and 3d10 Temporary Hit Points. Your Speed drops by 15 ft, you have Disadvantage on D20 Tests, and creatures you force to save have Advantage. When it ends, you must succeed on a DC 15 Constitution save or gain 1 Exhaustion level.")
add("Cap of Bravery", "Wondrous Item", "Uncommon", 0, "A cap woven from the remains of a snarite. While you wear it, you and your allies in a 30-ft Emanation have Advantage on saving throws to avoid or end the Frightened condition.")
add("Crimson Mist", "Wondrous Item", "Uncommon", 0, "A tiny bottle of pheromones taken from prey animals. As an action, spray it on a creature within 5 ft for 1 minute. Beasts and other creatures that must attack the nearest target go after the sprayed creature instead, as long as it is within 60 ft of the attacker.")
add("Enchanted Feather", "Wondrous Item", "Uncommon", 0, "A feather that sometimes grows on a rabenhex. While holding it, you can use an action to cast Remove Curse. Afterward the feather becomes nonmagical.")
SP["Enchanted Feather"] = {"sp": [["Remove Curse", 0]]}
add("Flammable Tincture", "Wondrous Item", "Uncommon", 0, "A swirling red and white liquid made from coldfire ooze. As an action, hurl the vial up to 30 ft at a target, which must succeed on a DC 10 Dexterity save or be coated. For 1 minute the creature loses any Immunity or Resistance to Fire damage and has Vulnerability to Fire damage instead.")
add("Morose Monocle", "Wondrous Item", "Uncommon", 0, "An opaque grey eyepiece that blocks normal sight in that eye. Through it you see only grief eaters and creatures suffering significant pain, sorrow or guilt, shown as white outlines out to 60 ft. The brighter the glow, the stronger the turmoil. You also have Advantage on Wisdom (Insight) checks to read a creature's emotions.")
add("Profane Charm", "Wondrous Item", "Uncommon", 0, "A charred feather from a fallen angel, wrapped in silver wire. While you wear it, your creature type appears to be Humanoid to Detect Evil and Good and similar effects.")
add("Ready Gunk", "Wondrous Item", "Uncommon", 0, "A sticky paste made from the powdered bone armor of a bone trader. After you treat a weapon, Shield or similar one-handed or two-handed item with it, you can use a Bonus Action to summon and equip that item if it is within 30 ft. After three uses, the paste loses its potency.", ch=[3, "1", "never", "Loses potency after 3 uses"])
add("Sun Shades", "Wondrous Item", "Uncommon", 0, "Black leather goggles with cloudy glass that fully hides your eyes. Donning or doffing them takes an action. While worn, you ignore your Sunlight Sensitivity and any other ill effects of sunlight, but the goggles block your Darkvision.")
add("Humble Frock", "Wondrous Item", "Uncommon", 1, "While you wear this frock and no armor, Opportunity Attack rolls against you have Disadvantage. If you have reached at least Stage 2 of the Seraph, you also have Advantage on saving throws to avoid revealing your true nature.")
add("Telltale Heart", "Wondrous Item", "Uncommon", 1, "A cherry-sized bloodstone heart taken from a poppet. While it is on your person, when you gain the Frightened condition you can make a DC 15 Wisdom save to end it. When you make an Intelligence check while holding it, you can listen to it for Advantage on that check. The stone cannot be used this way again until the next dawn.", ch=[1, "1", "dawn"])
add("Mask of the Maestro", "Wondrous Item", "Uncommon", 0, "A yew mask carved as a beast's face, with 3 charges. While wearing it, you can spend 1 charge to cast Polymorph on yourself for up to 1 minute. **Curse.** The mask is cursed. Wearing it curses you until Remove Curse or similar magic targets you, and you cannot remove it meanwhile.", ch=[3, "1", "never"])
SP["Mask of the Maestro"] = {"sp": [["Polymorph", 1]]}
add("Vilesmog Bomb", "Wondrous Item", "Uncommon", 0, "A smoky vial favored by poisoners. Throw it up to 30 ft with a Magic action and it breaks into a dark vapor in a 15-ft-radius Sphere that lasts 2 rounds. A creature that enters or starts its turn there loses any Resistance or Immunity to Poison damage and gains Vulnerability to it. The effect on the creature lasts 1 minute.")

# ---- Rare and above wondrous items
add("Adder Stone", "Wondrous Item", "Rare", 0, "A glassy, fruit-sized stone with a natural hole, often found where a marra died. The first time you would gain the Paralyzed condition while carrying it, the stone shatters and the condition is removed.")
add("Amulet of Curse Suppression", "Wondrous Item", "Very Rare", 1, "A glittering ivory and silver amulet. While you are attuned to it, the effects of any curses on you are nullified as if Remove Curse had ended them. When the amulet is removed or your attunement ends, every suppressed curse returns in full.")
add("Arc Rifle", "Wondrous Item", "Very Rare", 0, "A gnomish rifle of glass tubes and sparking coils, illegal in most regions of Etharis. It has 4 charges. As a Magic action, spend 1 charge to fire a 60-ft-long, 5-ft-wide Line of lightning. Each creature in it makes a DC 15 Dexterity save, taking 4d6 Lightning damage on a fail or half on a success. It regains 1d4 charges at dawn, and if you spend the last one, roll 1d20 and on a 1 the rifle becomes useless. It is said to destroy the soul of a creature it kills.", ch=[4, "1d4", "dawn"])
add("Blessed Reliquary", "Wondrous Item", "Rare", 1, "A small wooden or ivory box holding a piece of a saint. While it is on your person, you have Advantage on saving throws caused by Undead and can use each Channel Divinity feature one additional time. Once, when you use Turn Undead, you can give the targets Disadvantage on their saves, and you regain that use after a Long Rest.")
add("Cloak of the Listener", "Wondrous Item", "Rare", 0, "A cloak of ears that oozes yellow fluid. Wearing it, you can use an action for one of two effects. **Ooze.** A 10-ft square of waxy goo appears centered within 30 ft, and a creature entering or starting its turn there must succeed on a DC 15 Dexterity save or be Grappled (escape DC 15), for 1 minute. **Hide.** Cover your head to gain the Blinded condition, Blindsight 120 ft and hearing of all speech within 120 ft for 1 minute. Each effect works once until the next dawn.", ch=[2, "1", "dawn", "One use per effect"])
add("Cloak of the Mausgeist", "Wondrous Item", "Very Rare", 1, "A cloak of mausgeist fur lined with silk. You have Advantage on Wisdom (Perception) checks that rely on hearing and Advantage on saving throws against spells and other magical effects. As an action, cast Charm Person (save DC 13) from it. That use returns at the next dawn.", ch=[1, "1", "dawn"])
SP["Cloak of the Mausgeist"] = {"sp": [["Charm Person", 0]], "dc": 13}
add("Cloak of the Stygian Bat", "Wondrous Item", "Rare", 1, "A cloak of coarse black stygian bat hide. You have Advantage on Wisdom (Perception) checks that rely on hearing. As an action, gain a Fly Speed of 30 ft and Blindsight 120 ft for 1 minute, with Advantage on Dexterity saves while in the air. That use returns at the next dawn.", ch=[1, "1", "dawn"])
add("Cloak of Therianthropy", "Wondrous Item", "Rare", 1, "A spotted grey cloak of styrkvisnar hide. You have Advantage on Strength (Athletics) checks. As an action, turn into a wolf, eagle or seal for up to 1 hour, working as Polymorph, and revert with a Bonus Action. That use returns at the next dawn.", fx={"adv": ["Athletics"]}, ch=[1, "1", "dawn"])
SP["Cloak of Therianthropy"] = {"sp": [["Polymorph", 0]]}
add("Coat of Lies", "Wondrous Item", "Rare", 1, "A coat made from the tongues of a harvester of lies' victims. You gain a +1 bonus to AC and Advantage on Charisma (Deception) checks. It has 3 charges and regains all of them at dawn. As a Bonus Action, spend 1 charge so your next spell before the start of your next turn needs no Verbal or Somatic components.", by="a Spellcaster", fx={"ac": 1, "adv": ["Deception"]}, ch=[3, "all", "dawn"])
add("Coin of War and Fear", "Wondrous Item", "Rare", 1, "A dark coin with Empyreus on one face and Beleth on the other. As an action, flip it and roll a d6. On an even roll you get the Boon of Empyreus for 1 minute, with +2 AC and 1d4 added to your first attack roll each turn. On an odd roll you get the Boon of Beleth for 1 minute, with a 10-ft aura where an enemy ending its turn must succeed on a DC 14 Wisdom save or be Frightened until the end of its next turn, and you deal an extra 1d6 Psychic damage with weapon hits on Frightened creatures. Getting the same boon again before dawn deals 3d6 Radiant (Empyreus) or Necrotic (Beleth) damage to you instead.")
add("Collar of the Undead", "Wondrous Item", "Very Rare", 0, "As an action, place this collar on a Large or smaller Humanoid that died within the last 10 days. It returns to life with 1 Hit Point as an Undead that needs no food, sleep or air. Each dawn its Hit Point maximum drops by 1d4, and it crumbles to dust at 0 Hit Points or maximum. You can use a Bonus Action to command it within 60 ft, otherwise it takes the Dodge action. Removing the collar reduces it to 0 Hit Points.")
add("Faerie Crown", "Wondrous Item", "Very Rare", 1, "A crown woven of aromatic flowers. When you first don it after attuning, 1d6 + 3 butterflies flutter around it. When a melee attack hits you, use a Reaction to release one so the attack misses and destroys the butterfly. When all are gone, the crown crumbles to dust.")
add("Fin Symbiote", "Wondrous Item", "Rare", 1, "A tendril of Aberration flesh that melds with a Humanoid host. You have Advantage on Constitution saves, and when you would be moved against your will you can use a Reaction to cut that movement by 10 ft. With at least Stage 1 of the Aberrant Horror, add 2 to the save DCs of your Aberrant Horror Boons. You cannot end attunement, and if the fin is removed it regrows in 1d4 hours unless Remove Curse is cast on you first.")
add("Funeral Mask", "Wondrous Item", "Very Rare", 1, "A thin copper mask that molds to your face. As an action, change your appearance for 8 hours, including height, weight, features, voice and hair, though not your size or basic shape. A creature within 5 ft can use an action for a DC 20 Intelligence (Investigation) check to see the truth. With Stage 1 of the Lich, you gain +2 AC while the disguise holds. It can be used again after the next dawn.", ch=[1, "1", "dawn"])
add("Grenade of Remorse", "Wondrous Item", "Rare", 0, "A toxic substance harvested from the tears of a remorseful storm. As an action, hurl it at a point up to 30 ft away to burst in a 20-ft-radius Sphere. Each Aberration, Fiend and Undead there makes a DC 17 Constitution save, taking 8d6 Psychic damage on a fail or half on a success.")
add("Heaven's Herald", "Wondrous Item", "Very Rare", 0, "A golden trumpet that never tarnishes. As an action, blow it so up to 12 willing creatures within 600 ft become emboldened for 8 hours. Each has Immunity to the Frightened condition, Advantage on Wisdom saves, and its Hit Point maximum and current Hit Points rise by 2d10. A Fiend or Undead who blows it takes 8d6 Radiant damage. It can be used again after the next dawn.", ch=[1, "1", "dawn"])
add("Iron Fangs", "Wondrous Item", "Rare", 1, "Iron tooth caps inscribed with runes. You gain a +2 bonus to attack and damage rolls with your Bite attacks, and they deal your choice of Force or Piercing damage.")
add("Knifewing Cape", "Wondrous Item", "Rare", 1, "A cloak sewn from the skins of twenty knifewings. You gain a +1 bonus to AC, and when you fall you descend 60 ft per round and take no damage from falling.", fx={"ac": 1})
add("Magebane Bomb", "Wondrous Item", "Rare", 0, "A bubbling liquid distilled from a magebane ooze. Make a ranged weapon attack to throw it at a weapon, armor or spellcaster. On a hit the target takes 1d6 Acid damage. A struck weapon takes a -1 penalty to attacks and damage, and struck armor takes -1 to AC, both until the wielder or wearer finishes a Long Rest. A hit spellcaster has -1 to spell attack rolls and -1 to its spell save DCs for 1 minute.")
add("Magical Prosthetics", "Wondrous Item", "Unknown", 0, "A Prosthetic made to copy a wondrous item or ring worn on that body part, such as a leg that works as Boots of Elvenkind or a hand that works as a Ring of Protection. It has the same rarity as the item it copies and counts as wearing that item, so you cannot also wear another item for that slot. Prosthetics are described in the Player's Guide.")
add("Muscle Graft", "Wondrous Item", "Very Rare", 1, "A graft of bugbear vampire muscle that melds to its host. Your Strength rises by 2, to a maximum of 30. On attuning you must succeed on a DC 15 Constitution save or your Constitution drops by 2 (minimum 1). **Curse.** Attuning curses you for 1 year or until Remove Curse or similar magic, and you cannot end attunement. You crave raw meat and blood, and each week you must succeed on a DC 10 Constitution save or become a Vampire Spawn with no progenitor.", fx={"abil": ["STR", 2, 30]})
add("Net of Maiden's Hair", "Wondrous Item", "Rare", 1, "A sweet-smelling headnet sewn from maiden's hair. While you wear it, you have Advantage on Charisma (Persuasion) checks. You can use a Bonus Action to make an ability check to end the Grappled condition on yourself, with Advantage on those checks.", fx={"adv": ["Persuasion"]})
add("Pharazorthok Sprout", "Wondrous Item", "Very Rare", 0, "A hand-sized fleshy sapling with writhing tentacle branches and yellow eyes. As an action, plant it in your space. While it is planted within 30 ft of you, you have Truesight 30 ft, and anyone in its space can uproot it with an action. If left in the ground for 1 minute, it uproots itself and becomes a Roper Hostile to you and your allies.")
add("Queen's Token", "Wondrous Item", "Legendary", 0, "A humble acorn given by a Faerie queen. While holding it, you can cast Wish, after which it teleports back to the queen. If the Wish would threaten the queen or her realm, it fails and the caster becomes an oak tree. Only a Wish cast with the token can reverse that.")
SP["Queen's Token"] = {"sp": [["Wish", 0]]}
add("Sangromancer's Vial", "Wondrous Item", "Rare", 1, "A vial of red glass and gold filigree. When you attune, fill it with your blood by rolling up to 10 of your Hit Point Dice and lowering your Hit Point maximum by the total. That creates a pool of Hit Point Dice you can spend instead of your own when you cast a Sangromancy spell. Each Long Rest restores a number of pool dice equal to half the number rolled. Ending attunement returns your maximum after a Long Rest.")
add("Sizzling Serum", "Wondrous Item", "Rare", 0, "A volatile concoction made from a potbelly's stomach-pot ichor. As a Magic action, hurl it at a Construct or object you see within 30 ft. The target makes a DC 15 Constitution save, taking 10d6 Fire damage on a fail or half on a success.")
add("Soulbond Stone", "Wondrous Item", "Rare", 0, "A heavy stone with a dusk-colored gem. Press it to a creature dead less than 1 minute to capture a fragment of its soul. It has 3 charges, and while holding it you can spend 1 to cast Speak with Dead as if the trapped soul's corpse were the target. When the last charge is gone, the stone shatters.", ch=[3, "1", "never", "Does not recharge"])
SP["Soulbond Stone"] = {"sp": [["Speak with Dead", 1]]}
add("Stalk Symbiote", "Wondrous Item", "Rare", 1, "An ocular organ from an Aberration that melds with a Humanoid host's skull. You have Advantage on Wisdom (Perception) checks and no Disadvantage on Initiative when surprised. With Stage 1 of the Aberrant Horror, you also have Blindsight 10 ft. You cannot end attunement, and if the stalk is removed it regrows in 1d4 hours unless Remove Curse is cast on you first.", fx={"adv": ["Perception"]})
add("Straitjacket", "Wondrous Item", "Rare", 1, "A stained grey jacket with long arms and restraining straps that takes 10 minutes to don or doff. Wearing it with no armor or Shield, you add your Intelligence modifier to AC and can cast spells without Somatic or Material components that lack a listed gp value. You have Disadvantage on weapon and Unarmed Strike attack rolls. With Stage 1 of the Aberrant Horror, you roll twice on the Unstable Form table and choose.")
add("Suit of the Lamb", "Wondrous Item", "Rare", 0, "Cozy woolen clothes made from poffer wool, with a shirt, trousers or kilt, and thick socks. While you wear them, you have Resistance to Lightning damage and ignore the effects of extreme cold weather.", fx={"res": ["Lightning"]})
add("Talisman of Tormach", "Wondrous Item", "Rare", 1, "A dreadful talisman made from a gore elemental's skull. When you kill a creature with a melee weapon or Unarmed Strike while wearing it, you gain 10 Temporary Hit Points for 1 minute. While you have any of them, your melee weapon attacks and Unarmed Strikes deal an extra 1d6 Necrotic damage on a hit.")
add("Thought Talker Orbs", "Wondrous Item", "Rare", 0, "A spying device of two crystal orbs, a marble-sized Emitter and a fist-sized Receiver. A Magic action touching them together activates them for 7 days. A creature entering the Emitter's 5-ft Sphere or starting its turn there makes a DC 13 Wisdom save, and on a success it is immune for 24 hours. On a fail, the Receiver's holder learns its surface thoughts for 1 minute, even if it leaves.")
add("Thricecall Mirror", "Wondrous Item", "Very Rare", 0, "An ornate iron hand mirror decorated with grasping hands. As a Magic action, speak an extraplanar being's true name into it three times to summon that Fey, Fiend, Celestial or similar creature within 5 ft of the mirror. It keeps its free will and may not be friendly. It cannot leave this plane for 1 minute, then returns home unless it can travel planes by itself.")
add("Wraps of Aphaeleon", "Wondrous Item", "Rare", 1, "Simple cloth fist wraps blessed by Aphaeleon, the Arch Seraph of temperance. While wearing them, you can spend 3 Focus Points on your turn to end the Incapacitated, Paralyzed or Stunned condition on yourself, with no action required.", by="a Monk")
add("Resuscitation Bomb", "Wondrous Item", "Rare", 0, "A foul concoction made from stinking sludge. As an action, throw the vial up to 10 ft to release vapor in a 30-ft-radius Sphere. Creatures there end the Incapacitated, Stunned and Unconscious conditions, and dying creatures have Advantage on their next Death Saving Throw. Any other creature must succeed on a DC 15 Constitution save or be Poisoned for 1 minute.")

# ---- Rings, rods and wands
add("Gold Boar Ring", "Ring", "Uncommon", 0, "A ring made from gold mane boar bristles. It sheds Bright Light in a 20-ft radius and Dim Light for 20 ft beyond. The light works even where magic fails or magical light would be suppressed.")
add("Mortal Coil", "Ring", "Very Rare", 1, "A ring of hundreds of rose gold wires coiled around the finger. If you die while wearing it, your soul enters the ring and your body stays alive and Stable at 0 Hit Points. When you regain Hit Points, your soul returns and the ring becomes a lump of lead.")
add("Ring of Hidden Desire", "Ring", "Uncommon", 0, "A rose gold band set with a heart-shaped obsidian. As a Magic action, pick a creature you see, which makes a DC 13 Wisdom save. On a fail, you learn its greatest desire, and on a success you learn nothing and it is immune to the ring. Creatures with Intelligence 3 or lower are unaffected. It works once and recharges at midnight.", ch=[1, "1", "never", "Recharges at midnight"])
add("Ring of Nightmares", "Ring", "Rare", 1, "A ring made with powdered brain of a restless lumberer, with 3 charges that return as 1d3 at dawn. As a Bonus Action, spend 1 charge to make the damage of the next spell you cast this turn Psychic. You are also immune to spells and abilities that disturb your sleep or cause nightmares.", by="a Spellcaster", ch=[3, "1d3", "dawn"])
add("Ring of Radiation", "Ring", "Uncommon", 0, "A ring of braided copper wire. When you cast a spell or use an ability that deals Cold, Fire or Lightning damage, its range is doubled.")
add("Ring of Veracity", "Ring", "Uncommon", 1, "A golden band stamped with smiling faces. You have Advantage on Wisdom (Insight) checks made with the Search action. As a Magic action, cast Zone of Truth (save DC 15) from it, and it cannot do so again until the next dawn.", ch=[1, "1", "dawn"])
SP["Ring of Veracity"] = {"sp": [["Zone of Truth", 0]], "dc": 15}
add("Star Metal Ring", "Ring", "Rare", 0, "A heavy steel ring set with shimmering star metal. While you wear it, your Unarmed Strikes are magical and deal Force damage.")
add("Rod of Ruin", "Rod", "Rare", 1, "A rod of stacked crystal spheres filled with smoke, with 3 charges that return at dusk. When a creature you see within 60 ft damages you while you hold it, use a Reaction and 1 charge to force a DC 15 Constitution save. On a fail it gains 1 Exhaustion level. If you have the Lich, the save is at Disadvantage and you gain 2d10 Temporary Hit Points when it fails.", ch=[3, "3", "dusk"])
add("Rod of the Pack Master", "Rod", "Very Rare", 1, "A driftwood rod carved with wolves and bears. While holding it, use a Magic action to cast Polymorph on any number of willing Humanoids within 30 ft, limited to Black Bear and Wolf forms. Targets keep their Intelligence, Wisdom and Charisma, the effect lasts 24 hours with no Concentration, and you can end it early. With Stage 1 of the Lycanthrope you can use it in your teeth in hybrid or kindred form. It recharges at dawn.", ch=[1, "1", "dawn"])
SP["Rod of the Pack Master"] = {"sp": [["Polymorph", 0]]}
add("Wand of Silence", "Wand", "Uncommon", 1, "A wand with 7 charges that regains 1d6 + 1 at dawn. While holding it, spend 1 charge to cast Silence from it (save DC 15). If you spend the last charge, roll a d20 and on a 1 the wand crumbles to ash.", by="a Spellcaster", ch=[7, "1d6+1", "dawn"])
SP["Wand of Silence"] = {"sp": [["Silence", 1]], "dc": 15}
add("Wand of the Poltergeist", "Wand", "Very Rare", 1, "A wand of swirled dark and white wood topped with a screaming skull, holding 7 charges that return as 1d6 + 1 at dusk. While holding it, spend charges to cast Animate Objects (4), Major Image (3) or Shatter (2), using your spell save DC. If you spend the last charge, roll a d20 and on a 20 the wand explodes into splinters.", by="a Spellcaster", ch=[7, "1d6+1", "dusk"])
SP["Wand of the Poltergeist"] = {"sp": [["Animate Objects", 4], ["Major Image", 3], ["Shatter", 2]]}
add("Nightmare Staff", "Staff", "Uncommon", 1, "A twisted staff made from a marra's remains, with 3 charges that return at dusk. When a creature you see within 60 ft damages you while you hold it, use a Reaction and 1 charge to force a DC 13 Intelligence save. On a fail it sees a phantasm and is Frightened until the end of its next turn, and if it was already Frightened it also takes 2d6 Psychic damage.", base=["Quarterstaff"], ch=[3, "3", "dusk"])
add("Staff of Briars", "Staff", "Uncommon", 0, "A wooden staff cut from braerog claws, with 10 charges. As a Magic action, spend 1 charge to raise rose vines over a 20-ft square centered within 5 ft of you, making it Difficult Terrain. The briars become nonmagical once made. It regains 1d6 + 4 charges at dawn, and if you spend the last one, roll a d20 and on a 1 the staff turns to rose petals.", base=["Quarterstaff"], ch=[10, "1d6+4", "dawn"])

# ---- Potions, elixirs and drugs
add("Aether Blood", "Potion", "Rare", 0, "A glowing purple liquid prized by spellcasters. For 1 minute, add 1 to the save DCs of your spells, and a spell that could use a higher slot has its effective level raised by 1. You can drink it safely a number of times equal to your Constitution modifier (minimum 1). Further doses cause addiction, which gives Disadvantage on Strength and Constitution checks and saves and gives attackers Advantage against you.")
add("Arcane Oil", "Potion", "Rare", 0, "A substance distilled from the jelly around a xakalonus brain. As a Bonus Action, coat one weapon or up to 20 pieces of ammunition. For 1 minute, nonmagical coated items grant +2 to attack and damage rolls. Magical coated items instead ignore a hraptnon's Immunity to magical weapons.")
add("Dreams Leaves", "Potion", "Uncommon", 0, "A hallucinogenic drug from a magically grown plant. You can fall into a trance with the Unconscious condition for 1 hour, which taking damage ends. If it lasts the full hour, once before your next Long Rest you can use a Reaction to reroll a D20 Test and take the new result. Doing so causes addiction, which gives Disadvantage on saving throws until you take another dose or finish a Long Rest.")
add("Elixir of Elemental Spittle", "Potion", "Rare", 0, "A foul liquid made from elemental troll saliva. For 1 minute, you can use a Bonus Action to spit at a creature within 5 ft, which takes 2d6 damage of the troll's type unless it succeeds on a DC 12 Dexterity save. If it rolls a natural 20 on the save, the potion explodes inside you for 6d6 damage of that type and the effect ends.")
add("Elixir of Life Protection", "Potion", "Rare", 0, "A thick, chalky mixture. For 10 minutes after drinking it, your Hit Point maximum cannot be reduced.")
add("Full Moon Extract", "Potion", "Uncommon", 0, "A powder ground from werewolf organs. For 1 hour your Strength score becomes 19 (if lower), and you have Advantage on Strength checks and saves. You can use it safely a number of times equal to your Constitution modifier (minimum 1). Further doses cause addiction, giving Disadvantage on Dexterity checks and saves and Advantage to attackers, and a dose to ease it forces a DC 10 Charisma save or a violent rage for 1 minute.", fx={"setsc": ["STR", 19]})
add("Gristaline", "Potion", "Uncommon", 0, "A gruesome mixture of ground mouruge bone, rotten meat and mud. For 1 hour your Strength score becomes 19 (if lower), but you have Disadvantage on Intelligence checks and saves.", fx={"setsc": ["STR", 19]})
add("Hogs' Wash", "Potion", "Rare", 0, "A foul tea brewed from powdered doom boar tusks. Drinking it has the effect of Remove Curse. It also works as a component for removing a Shadowsteel curse.")
add("Hunter's Zeal", "Potion", "Rare", 0, "A glowing green liquid that sends the immune system into overdrive. For 1 hour you have Immunity to Poison damage and the Poisoned condition and Advantage on saves to avoid being cursed. When it ends, you gain 1 Exhaustion level.", fx={"imm": ["Poison"], "condImm": ["Poisoned"]})
add("Inquisitor's Draught", "Potion", "Legendary", 0, "A silver syrup made to capture mages and also to break free of cursed items. For 1 hour you cannot attune to magic items, and you can use an action to sever all your attunements, even to cursed items. If you are still attuned to any magic item when the hour ends, you die.")
add("Lycanthropy Antidote", "Potion", "Rare", 0, "A silvery potion flecked with red, made with fzeg blood. Drinking it removes the curse of lycanthropy.")
add("Potion of Glacial Resistance", "Potion", "Rare", 0, "A salty, slightly warm brew of ground keppmir horns. For 1 hour you can breathe underwater and have Resistance to Cold damage.", fx={"res": ["Cold"]})
add("Potion of Harm", "Potion", "Rare", 0, "A failed attempt at a Potion of Heal that looks identical without level 3 or higher divination. Drinking it makes you roll 1d4 and set your Hit Points to that total. On a creature at 0 Hit Points, it causes an instant Death Saving Throw failure and starts it dying if it was Stable.")
add("Potion of Heal", "Potion", "Very Rare", 0, "An ebon liquid made from the remains of a downcast vampire. Drinking it restores all your Hit Points.")
