add("Brazen Armor", "Armor", "Very Rare", 1, "Plate armor shaped from an Empyrean brazen bull that gleams in direct sunlight. You gain a +1 bonus to AC and have Resistance to Fire and Radiant damage while wearing it.", base=["Plate Armor"], fx={"ac": 1, "res": ["Fire", "Radiant"]})
