add("Cinder Coat", "Armor", "Very Rare", 1, "A floor-length leather duster the color of dying embers. You gain a +2 bonus to AC while wearing it. It has 3 charges, and when you hit with a melee attack against a creature below its Hit Point maximum you can spend 1 to deal an extra 1d10 Fire damage. It regains 1d3 charges at dawn.", base=["Leather Armor"], fx={"ac": 2}, ch=[3, "1d3", "dawn"], xd=["Wounded target: +1d10 Fire"])
add("Glass-Studded Armor", "Armor", "Rare", 1, "Studded leather armor set with glass shards. You have Resistance to Radiant damage while wearing it. Whenever a creature hits or misses you with a melee attack, it takes 3 Piercing damage, though it can choose Disadvantage on its attack roll to avoid that.", base=["Studded Leather Armor"], fx={"res": ["Radiant"]})
add("Iridescent Armor", "Armor", "Rare", 1, "A breastplate forged from a giant dragonfly carapace with a gossamer cape. You gain a +1 bonus to AC while wearing it. As an action, turn the cape into wings for 1 hour to gain a Fly Speed of 30 ft. With Stage 1 of the Fey, the wings last 2 hours and give a Fly Speed of 60 ft. It can be used again after the next dawn.", base=["Breastplate"], fx={"ac": 1}, ch=[1, "1", "dawn"])
add("Lodestone Armor", "Armor", "Very Rare", 1, "Plate armor lined with magnetic lodestone from another plane. As a Bonus Action, boost its polarity for 1 minute so loose stone and minerals cling to it, giving +1 AC and cutting your Speed by 5 ft. Using it again while active adds +1 AC and another 5 ft of Speed reduction, to a maximum of +4 AC and 20 ft. At the maximum you cannot reactivate it until the duration ends.", base=["Plate Armor"])
add("Paragon's Plate", "Armor", "Legendary", 1, "An ancient full suit of plate that hides every part of you. You are immune to the Unconscious condition. At 0 Hit Points you must still make Death Saving Throws but can keep moving and acting, and if you die you can keep acting for 1 minute without speaking, casting or concentrating. **Curse.** It is revealed by Identify or attunement. It cannot be removed while attuned, and you automatically fail all Death Saving Throws.", base=["Plate Armor"], fx={"condImm": ["Unconscious"]})
add("Pigskin Armor", "Armor", "Uncommon", 0, "Supple armor made from ogre swine hide. It counts as light armor rather than medium. When a Critical Hit is scored on you, roll 1d20 and on a 17 to 20 it becomes a normal hit. While wearing it, you snore uncontrollably in sleep and your food intake doubles.", base=["Hide Armor"])
add("Quakescale Armor", "Armor", "Uncommon", 0, "Scale mail from quake drake scales that rumbles softly in storms. While wearing it, you have Resistance to Thunder damage.", base=["Scale Mail"], fx={"res": ["Thunder"]})
add("Second Skin", "Armor", "Very Rare", 1, "A harness woven from slain lycanthrope hides that melds into your flesh when you attune. Your AC is 14 + your Dexterity modifier. When you take Bludgeoning, Piercing or Slashing damage from a nonsilver source, you can use a Reaction to halve it, rounding down. You have Disadvantage on Charisma checks to interact with lycanthropes.", base=["Hide Armor"], fx={"ac": 2})

