add("Malleus Macabre", "Weapon", "Very Rare", 1, "A jagged bludgeon that is the object form of a kokela. You gain a +4 bonus to damage rolls, and attack rolls with it Critically Hit on a 19 or 20 (17 to 20 if you already have a wider range). **Curse.** Attuning curses you until you spend 1 year at least a mile away. Meanwhile you will not part with it, have Disadvantage with other weapons unless no foe within 60 ft is seen or heard, and a Critical Hit has a 25 percent chance to cast level 9 Cloudkill centered on you.", by="a Fighter or Barbarian", base=["Greatclub"], fx={"dmg": 4})
add("Staff of the Sorcerer King", "Weapon", "Legendary", 1, "An ebony staff with a bronze spear tip and blades carved as a winged scarab. It works as a magic Spear giving +2 to attack and damage, and you are proficient with it while attuned. Holding it also gives +2 to spell attack rolls, Humanoids have a -2 penalty to saves against your spells, and you have Advantage on saves against spells that target only you. **Cursed.** You will not part with it and have Disadvantage with other weapons. Each midnight, a DC 17 Constitution save failure cuts your Hit Point maximum by 10 (not Undead), only a Wish restores it, and at 0 you die and rise as a Wight.", base=["Spear"], fx={"atk": 2, "dmg": 2, "spellAtk": 2})
add("Ardor", "Weapon", "Artifact", 1, "A smoldering battleaxe with silver accents, forged by a fiendish smith for a scion of darkness. You gain a +3 bonus to attack and damage rolls, a hit adds 2d10 Necrotic damage, and you are immune to the Charmed, Frightened, Paralyzed and Stunned conditions while holding it. A Bonus Action sets it hovering, and later Bonus Actions move it up to 50 ft and either grasp it or make it attack. You can cast Bane, Bestow Curse or Incendiary Cloud from it (save DC 18), once each until dawn. Only Zeal can damage it (AC 21, 300 Hit Points).", base=["Battleaxe"], fx={"atk": 3, "dmg": 3, "condImm": ["Charmed", "Frightened", "Paralyzed", "Stunned"]}, xd=["+2d10 Necrotic"], ch=[3, "3", "dawn", "One use per spell. Tick one for each spell cast"])
