# ---- Corrupted artifacts with Aspirant, Adept and Master tiers (cumulative texts)
TIER = ("Aspirant", "Adept", "Master")
def tiers(name, typ, intro, parts, **o):
    for i, t in enumerate(TIER):
        body = " ".join("**%s.** %s" % (TIER[j], parts[j]) for j in range(i + 1))
        add("%s (%s)" % (name, t), typ, "Artifact", 1, intro + " " + body, **o)

tiers("Dämglesvir", "Weapon",
  "A black-bladed longsword once drawn only by the emperor. It carries a curse at every tier.",
  ["You gain +2 to attack and damage rolls with it, and any weapon you wield deals an extra 1d6 Force damage. Curse: you have Disadvantage on Constitution saves.",
   "A creature it damages cannot regain Hit Points until the start of your next turn. When you take the Attack action, you can make one attack a sweeping strike against each creature of your choice in reach, a number of times equal to your Proficiency Bonus per Long Rest. Curse: each time you hit with it, your Hit Point maximum drops by 1 until a Long Rest.",
   "When you hit, you can try to slay a creature with 100 Hit Points or less, which dies on a failed DC 20 Constitution save, once per Long Rest. Curse: after you hit with it, you cannot regain Hit Points until the start of your next turn and healing gives Temporary Hit Points instead."],
  base=["Longsword"], fx={"atk": 2, "dmg": 2}, xd=["+1d6 Force"])

tiers("Hearthfire Breastplate", "Armor",
  "A corrupted breastplate, once golden and radiant, now black and writhing. It carries a curse at every tier.",
  ["You can cast Shield a number of times equal to your Proficiency Bonus per Long Rest, and gain +2 to AC and saving throws. Curse: you have Disadvantage on Dexterity saves.",
   "As a Magic action, give up to six creatures within 30 ft 1d4 + 5 Temporary Hit Points (Proficiency Bonus times per Long Rest), and others gain +2 AC while holding those points. Curse: when an ally within 60 ft loses such points, you take Psychic damage equal to half the loss, which cannot be reduced.",
   "When a creature you see within 30 ft takes damage, use a Reaction to give it Immunity to all damage until the start of your next turn, once per Long Rest. Curse: when an ally you see drops to 0 Hit Points you are Frightened for 1 minute, or Paralyzed if it dies, and you can repeat a DC 16 Wisdom save each turn to end it."],
  base=["Breastplate"], fx={"ac": 2, "save": 2})
for _t in TIER: SP["Hearthfire Breastplate (%s)" % _t] = {"sp": [["Shield", 0]]}

tiers("Indorius's Crown", "Wondrous Item",
  "A crown that grants authority but not wisdom, with 12 charges that return as 2d4 + 4 at dawn. It carries a curse at every tier.",
  ["You have Advantage on Charisma checks and saves. Spend charges to cast Compulsion (4), Dominate Person (5), Hellish Rebuke (1), Hold Person (2) or Suggestion (2) from it (save DC 18). Curse: Disadvantage on Wisdom (Insight) checks and Wisdom saves.",
   "As a Bonus Action, make a Friendly creature that sees or hears you use its Reaction for a weapon attack, Unarmed Strike or a cantrip or level 2 or lower spell, Proficiency Bonus times per Long Rest. Friendly creatures within 10 ft add 1d4 to attack rolls and saves. Curse: an ally within 10 ft that misses or fails a check is Frightened until the end of its next turn.",
   "After a Charisma check, you can replace the roll with a 14. You can cast Dominate Monster and Power Word Stun from it (save DC 18), but after casting either you cannot cast both again until a Long Rest. Curse: with no Friendly creature within 10 ft, you have Disadvantage on attack rolls and cannot concentrate."],
  ch=[12, "2d4+4", "dawn"])
for _t in TIER:
    _n = "Indorius's Crown (%s)" % _t
    _sp = [["Compulsion", 4], ["Dominate Person", 5], ["Hellish Rebuke", 1], ["Hold Person", 2], ["Suggestion", 2]]
    if _t == "Master": _sp += [["Dominate Monster", 0], ["Power Word Stun", 0]]
    SP[_n] = {"sp": _sp, "dc": 18}

tiers("Ulmyr's Eye", "Wondrous Item",
  "A crystal ball of shifting smoke that shows disturbing visions, with 12 charges that return as 2d4 + 4 at dawn. It carries a curse at every tier.",
  ["You know Guidance and spend charges to cast Augury (2), Clairvoyance (3), Detect Thoughts (2), Divination (4) or Scrying (5) from it (save DC 18). Curse: Disadvantage on Wisdom (Perception) and Intelligence (Investigation) checks.",
   "While holding it, use a Reaction to give Advantage or Disadvantage on a D20 Test made by a creature you see within 60 ft, Proficiency Bonus times per Long Rest. You can also spend charges equal to a prepared spell's level to cast it without a slot. Curse: after a Long Rest you must succeed on a DC 14 Wisdom save or gain only a Short Rest's benefits.",
   "While holding it, cast Foresight from it with no Material component and a 1 hour duration, once per Long Rest. Curse: when you roll Initiative, the orb casts Phantasmal Killer on you (save DC 14), and extreme distress may also trigger it."],
  ch=[12, "2d4+4", "dawn"])
for _t in TIER:
    _n = "Ulmyr's Eye (%s)" % _t
    _sp = [["Guidance", 0], ["Augury", 2], ["Clairvoyance", 3], ["Detect Thoughts", 2], ["Divination", 4], ["Scrying", 5]]
